$(document).ready(function(){$("#trazabilidad").addClass("selected"),$("#trazabilidad a").addClass("active"),initView()});const commonsFilters={status:"",period:"month",dateFrom:null,dateTo:null,search:""};function initView(){buildStatus(),fetchList()}function fetchList(){sendAjax({endpoint:"/Trazabilidad/list",type:"POST",data:commonsFilters,beforeSend:function(){loadingTable("lists")},onSuccess:t=>{setTimeout(()=>{t.success?buildList(t.data):Notify(2,t.message)},1200)}})}function buildList(t){let n="";t.forEach(t=>{n+=`\n            <tr>\n                <td>\n                    <div class="fw-bold">${t.batch_code}</div>\n                    <div class="text-muted fs-2">${t.notes||""}</div>\n                </td>\n                <td>${formatModule(t.batch_type)}</td>\n                <td>${t.product}</td>\n                <td>${t.subproduct}</td>\n                <td>${t.production_date}</td>\n                <td>${t.expiration_date}</td>\n                <td class="text-center user-select-none">\n                    <a href="${ruta_web}/Trazabilidad/${t.id}" class="btn-admin">\n                      <span class="material-symbols-outlined edit text-empresa btn-admin h1" title="Historial">history</span>\n                    </a>\n                </td>\n            </tr>\n        `});const a=`\n        <div class="table-responsive mt-3">\n            <table class="table table-hover border text-nowrap" id="table">\n                <thead class="bg-light user-select-none">\n                    <tr>\n                        <th>Código Lote</th>\n                        <th>Módulo Origen</th>\n                        <th>Producto</th>\n                        <th>Subproducto</th>\n                        <th>Fecha de Producción</th>\n                        <th>Fecha de Expiración</th>\n                        <th class="text-center" data-orderable="false">Acción</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    ${n}\n                </tbody>\n            </table>\n        </div>\n    `;$("#lists").html(a),formatDatatable("#table",2,"asc")}function formatModule(t){switch(t){case"production":return'<span class="badge bg-warning">Producción</span>';case"purchase":return'<span class="badge bg-primary">Compra</span>';default:return t}}function buildStatus(){$("#status").empty().html('\n    <div class="d-flex flex-column flex-md-row gap-2">\n        <div class="w-100 w-md-auto"></div>\n        <div class="ms-md-auto">\n            <div class="dropdown">\n                <button class="btn btn-light btn-lg d-flex align-items-center dropdown-toggle w-100 w-md-auto" type="button" data-bs-toggle="dropdown" data-bs-auto-close="outside" aria-expanded="false">\n                    <span class="material-symbols-outlined">calendar_month</span>\n                    <span class="ms-2" id="periodoSeleccionado">Este mes</span>\n                </button>\n                <div class="dropdown-menu p-2" style="min-width: 280px;">\n                    <a class="dropdown-item d-flex align-items-center periodo-item"\n                        href="#"\n                        data-value="all">\n                        <span class="material-symbols-outlined">date_range</span>\n                        <span class="ms-2">Todos</span>\n                    </a>\n                    <a class="dropdown-item d-flex align-items-center periodo-item"\n                        href="#"\n                        data-value="today">\n                        <span class="material-symbols-outlined">today</span>\n                        <span class="ms-2">Hoy</span>\n                    </a>\n                    <a class="dropdown-item d-flex align-items-center periodo-item"\n                        href="#"\n                        data-value="week">\n                        <span class="material-symbols-outlined">view_week</span>\n                        <span class="ms-2">Esta semana</span>\n                    </a>\n                    <a class="dropdown-item d-flex align-items-center periodo-item"\n                        href="#"\n                        data-value="month">\n                        <span class="material-symbols-outlined">calendar_month</span>\n                        <span class="ms-2">Este mes</span>\n                    </a>\n                    <a class="dropdown-item d-flex align-items-center periodo-item"\n                        href="#"\n                        data-value="last_month">\n                        <span class="material-symbols-outlined">history</span>\n                        <span class="ms-2">Mes pasado</span>\n                    </a>\n                    <hr class="dropdown-divider">\n                    <a class="dropdown-item d-flex align-items-center periodo-item"\n                        href="#"\n                        data-value="custom"\n                        id="btnPersonalizado">\n                        <span class="material-symbols-outlined">edit_calendar</span>\n                        <span class="ms-2">Personalizado</span>\n                    </a>\n                    <div id="rangoPersonalizado" class="px-2 pt-2 d-none">\n                        <label class="form-label small mb-1">Desde</label>\n                        <input\n                            type="date"\n                            id="fechaDesde"\n                            class="form-control form-control-sm mb-2">\n                        <label class="form-label small mb-1">Hasta</label>\n                        <input\n                            type="date"\n                            id="fechaHasta"\n                            class="form-control form-control-sm mb-2">\n                        <button\n                            id="btnAplicarRango"\n                            class="btn btn-primary btn-sm w-100">\n                            Aplicar\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <div class="ms-2">\n            <div class="position-relative">\n                <span class="material-symbols-outlined position-absolute top-50 start-0 translate-middle-y ms-3">search</span>\n                <input type="text" class="form-control form-control-lg ps-5" id="tablebuscador" placeholder="¿Buscas algo?">\n            </div>\n        </div>\n    </div>'),dropdownFormat()}function dropdownFormat(){const t=document.getElementById("periodoSeleccionado"),n=document.getElementById("rangoPersonalizado");t&&(document.querySelectorAll(".periodo-item").forEach(a=>{a.addEventListener("click",function(a){a.preventDefault();const e=this.dataset.value,s=this.querySelector(".ms-2").textContent;"custom"!==e?(commonsFilters.period=e,commonsFilters.dateFrom=null,commonsFilters.dateTo=null,t.textContent=s,n.classList.add("d-none"),fetchList()):n.classList.remove("d-none")})}),document.getElementById("btnAplicarRango")?.addEventListener("click",function(){const a=document.getElementById("fechaDesde").value,e=document.getElementById("fechaHasta").value;if(!a||!e)return void Notify(2,"Debe seleccionar ambas fechas");commonsFilters.period="custom",commonsFilters.dateFrom=a,commonsFilters.dateTo=e;const s=formatearFecha(a),o=formatearFecha(e);t.textContent=`${s} - ${o}`,n.classList.add("d-none"),fetchList()}))}function formatearFecha(t){const[n,a,e]=t.split("-");return`${e}/${a}/${n}`}